/* ==UserStyle==
@name Porkbun Catppuccin
@namespace github.com/catppuccin/userstyles/styles/porkbun
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/porkbun
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/porkbun/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aporkbun
@description Soothing pastel theme for Porkbun
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("porkbun.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    &,
    body {
      background-color: @base;
      color: @text;
    }

    --cloudflare_on: @peach;
    --porkbun_danger: @red;
    --porkbun_warning: @yellow;
    --porkbun_success: @green;
    --porkbun_pink_hover: darken(@accent, 5%);
    --porkbun_pink: @accent;
    --porkbun_gold: @yellow;
    --porkbun_pink_light: lighten(@accent, 5%);
    --porkbun_pink_medium: @accent;
    --porkbun_dark_gray: @text;
    --porkbun_light_gray: @surface0;
    --porkbun_medium_gray: @overlay1;
    --porkbun_white: @mantle;
    --blue_link: @blue;
    --blue_link_hover: @sapphire;
    --headerMenuLink_color: @text;
    --headerMenuLink-hover_color: @text;
    --homepageBlurb_color: @text;

    /* Misc */

    .text-muted {
      color: @subtext0;
    }
    .text-danger {
      color: @red;
    }
    .text-success {
      color: @green;
    }

    .badge-porkbun {
      background-color: @surface0;
      color: @text;
    }

    .alert-info {
      background-color: fade(@blue, 30%);
      color: @blue;
      border-color: @blue;
    }

    .alert-warning {
      background-color: fade(@yellow, 30%);
      color: @yellow;
      border-color: @yellow;
    }

    .alert-danger {
      background-color: fade(@red, 30%);
      color: @red;
      border-color: @red;
    }

    hr {
      border-top-color: @surface1;
    }

    /* Inline overrides */

    [style*="background-color:white;"],
    [style*="background-color: rgb(248, 248, 248);"] {
      background-color: @surface0 !important;
    }
    [style*="color:black;"],
    [style*="color: white;"] {
      color: @text !important;
    }

    &[stylus-iframe="https://porkbun.com"],
    #beacon-container-body {
      background-color: transparent;

      .hsds-beacon button {
        background-color: @accent;

        [class*="FabButtoncss__FabBackgroundUI"] > svg {
          fill: @accent;
        }

        > span {
          color: @crust;
        }
      }
    }

    /* Buttons */

    .btn-default,
    .sortByPriceButton {
      &:not(.searchAddRemoveIcon, .searchAddRemoveIconSideBar) {
        background-color: @surface0;
        color: @text;
        border-color: @surface1;
      }

      &:hover {
        background-color: @surface1;
        color: @text;
      }
    }

    .btn-primary {
      background-color: @accent;
      border-color: @accent;
      color: @crust;

      &:hover {
        background-color: darken(@accent, 5%);
      }
    }

    .btn-danger {
      background-color: @red;
      border-color: @red;
      color: @crust;
    }

    .btn-success {
      background-color: @green;
      border-color: @green;
      color: @crust;
    }

    .btn-success-light {
      background-color: @green;
      color: @crust;
    }

    .btn-porkbun-white-borderless,
    .btn-porkbun-white:hover,
    .btn-porkbun-white:focus {
      color: @text;
    }

    .btn-porkbun-white.active {
      color: @crust;

      .text-muted {
        color: @surface0;
      }
    }

    /* Inputs */

    .slider {
      background-color: @red;

      &::before {
        background-color: @crust;
      }
    }

    .dropdown-menu {
      background-color: @surface0;

      > li > a {
        color: @text;

        &:hover {
          background-color: @surface1;
        }
      }

      .divider {
        background-color: @surface1;
      }
    }

    .form-control {
      background-color: @mantle;
      color: @text;
      border-color: @surface0;

      &:focus {
        box-shadow: 0 0 8px fade(@accent, 50%);
      }
    }

    select:not([multiple]) {
      -webkit-appearance: auto;
    }

    /* Table dividers */

    .table {
      > tbody,
      > tfoot,
      > thead {
        > tr {
          > th,
          > td {
            border-top-color: @surface1;
          }
        }
      }

      > thead > tr > th {
        border-bottom-color: @surface2;
      }

      [style*="border-top:2px solid gray;"] {
        border-top-color: @surface2 !important;
      }
    }

    .table-bordered {
      border-color: @surface1;

      > tbody,
      > tfoot,
      > thead {
        > tr {
          > th,
          > td {
            border-color: @surface1;
          }
        }
      }
    }

    /* Main */

    .headerContainer,
    footer > div {
      background-color: @crust !important;
    }

    #headerBrandLogo,
    #footerLogo {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144" fill="@{crust}"><circle fill="@{accent}" cx="72" cy="72" r="56.3"/><path d="M43.1 43.2c5 1.1 9.8 2.9 14.1 5.3-5.1 2.6-9.4 6.5-12.5 11.3-2-2.7-3.1-6.1-3.1-9.7q0-3.75 1.5-6.9"/><path d="M102.4 95.2c0 3.1-2.5 5.6-5.6 5.6s-5.6-2.5-5.6-5.6v-4.5H52.7v4.5c0 3.1-2.5 5.6-5.6 5.6s-5.6-2.5-5.6-5.6V78.1c0-16.5 12.8-30.5 29.3-31.1 17.3-.6 31.5 13.2 31.5 30.4z"/><path d="M99.3 59.8c-3.1-4.8-7.4-8.7-12.5-11.3 4.4-2.4 9.1-4.2 14.1-5.3q1.5 3.15 1.5 6.9c0 3.6-1.2 6.9-3.1 9.7"/><path fill="@{accent}" d="M85.3 71.4c-.4-.2-.8-.1-1 .2-.4.6-.9 1-1.6 1.4v-.5c0-1.4-.5-2.7-1.3-3.7-.6-.9-1.6-1.4-2.8-1.4-1.9 0-3.5 1.6-3.5 3.5 0 .8.3 1.6.8 2.2.6.7 1.3 1.3 2.2 1.7-.6.3-1.2.5-1.9.5-.8 0-1.4.7-1.4 1.4 0 .8.6 1.4 1.4 1.4h.7c2.2 0 4.2-1.3 5.1-3.1 1.5-.4 2.7-1.4 3.5-2.7.3-.2.2-.7-.2-.9m-5.7 1.9c-.9-.3-1.7-.8-2.2-1.6-.2-.2-.3-.5-.3-.8 0-.8.6-1.4 1.4-1.4.7 0 1.4.6 1.4 1.3 0 .2.1.4.1.7.1.6-.1 1.3-.4 1.8"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }

    .reviewWidget {
      .googleReviewCount {
        color: @subtext1;
      }

      .fas[class*="fa-star"] {
        color: @yellow;
      }
    }

    .homepageBulletIconFontAwesome {
      color: @subtext0;
    }
    .homePageSupportOptionCenterRight {
      border-color: @surface0;
    }

    #domainSearchBulkDropButton {
      &:hover,
      &:active,
      &:target,
      &:focus {
        background-color: @surface0;
      }
    }

    #searchResultsContainer {
      background-color: transparent;

      .sideBarSearchResults {
        border-color: @surface0;
      }
    }
    .searchResultsTldLetterBox {
      border-color: @surface1;
    }

    .cartBox {
      border-color: @surface1;
    }
    .cartSummaryBoxFreeList > li::before {
      color: @subtext0;
    }

    .marketplaceRow {
      border-top-color: @surface0;
    }

    .domainsPricingAllExtensionsHeader {
      background-color: transparent;
    }

    #homePagePricingContainer {
      background-color: transparent;
    }

    .hostingBox {
      border-color: @surface0;
    }

    .well {
      background-color: @base;
      border-color: @surface0;
    }

    .modal-content {
      background-color: @base;

      .close {
        color: @text;
        opacity: 1;
      }
    }

    .nav-tabs {
      border-bottom-color: @surface0;
    }
  }
}

